def countSubmatrices(matrix, target):
    R, C = len(matrix), len(matrix[0])
    total = 0
    for top in range(R):
        col = [0] * C
        for bottom in range(top, R):
            row = matrix[bottom]
            seen = {0: 1}
            pre = 0
            for c in range(C):
                col[c] += row[c]
                pre += col[c]
                total += seen.get(pre - target, 0)
                seen[pre] = seen.get(pre, 0) + 1
    return total
